  "bots.setup.callbackUrlTitle": "URL de callback",
  "bots.setup.callbackUrlDescription.webhook":
    "Seu sistema externo deve enviar callbacks de mensagens recebidas para este endereço. Respostas assíncronas de saída ainda usam a URL de Webhook informada à esquerda.",
  "bots.setup.callbackUrlDescription.webhookBind":
    "A vinculação por webhook usa o mesmo endpoint: envie aqui uma solicitação de callback privada com text = /bind <code>.",
  "bots.setup.guide.telegram.create.1": "Abra o @BotFather no Telegram e crie um novo bot.",
  "bots.setup.guide.telegram.create.2":
    "Copie o token da API HTTP retornado pelo BotFather e cole-o neste formulário.",
  "bots.setup.guide.telegram.create.3":
    "É útil abrir a conversa privada do bot agora, pois o comando de vinculação deve ser enviado por lá.",
  "bots.setup.guide.telegram.bind.1":
    "Volte ao Telegram e abra a conversa privada com o bot que você criou.",
  "bots.setup.guide.telegram.bind.2":
    "Se a conversa nunca foi iniciada, pressione Iniciar ou envie qualquer mensagem primeiro, depois envie {command}.",
  "bots.setup.guide.telegram.bind.3": "Volte aqui depois que o Telegram confirmar a vinculação.",
  "bots.setup.guide.weixin.create.1":
    "Inicie o login por QR code do Weixin, escaneie o QR code com o Weixin e confirme no celular.",
  "bots.setup.guide.weixin.create.2":
    "O Biolecce Code salva automaticamente o bot_token retornado pelo iLink; após escanear, envie qualquer mensagem ao bot no Weixin para ativar a conversa.",
  "bots.setup.guide.weixin.create.3":
    "O Biolecce Code usa um cliente iLink integrado: `/ilink/bot/getupdates` para long polling e `/ilink/bot/sendmessage` para respostas.",
  "bots.setup.guide.weixin.bind.1": "Abra a conversa direta do Weixin que deseja vincular.",
  "bots.setup.guide.weixin.bind.2": "Envie {command}.",
  "bots.setup.guide.weixin.bind.3":
    "Volte aqui após a vinculação ser concluída para finalizar os padrões de espaço de trabalho e CLI.",
  "bots.setup.guide.feishu.create.1":
    "Crie um app próprio no console de desenvolvedor do Feishu/Lark e ative o recurso de bot.",
  "bots.setup.guide.feishu.create.2":
    "Copie o App ID e o App Secret e ative eventos de conexão persistente para `im.message.receive_v1` e ações de cartão.",
  "bots.setup.guide.feishu.create.3":
    "Escolha aqui o domínio correspondente do Feishu ou Lark e cole as credenciais no formulário.",
  "bots.setup.guide.feishu.bind.1":
    "Instale o app no seu tenant e abra uma conversa direta com o bot.",
  "bots.setup.guide.feishu.bind.2": "Envie {command} nessa conversa direta.",
  "bots.setup.guide.feishu.bind.3":
    "Volte aqui após a vinculação ser concluída para finalizar os padrões de espaço de trabalho e CLI.",
  "bots.setup.guide.webhook.create.1":
    "O modo webhook não exige um bot nativo no produto de terceiros; sua integração só precisa enviar mensagens via POST para o Biolecce Code.",
  "bots.setup.guide.webhook.create.2":
    "Defina primeiro um segredo compartilhado; adicione também uma URL de webhook de saída se quiser que respostas assíncronas sejam enviadas de volta.",
  "bots.setup.guide.webhook.create.3":
    "Mantenha um userId estável por usuário externo para que a vinculação e o contexto futuro se refiram à mesma pessoa.",
  "bots.setup.guide.webhook.bind.1":
    "Envie via POST um callback de mensagem privada para o endpoint `/api/bots/webhook` do Biolecce Code.",
  "bots.setup.guide.webhook.bind.2":
    "O payload deve incluir pelo menos este botId, um userId estável, `chatType: \"private\"` e definir text como {command}.",
  "bots.setup.guide.webhook.bind.3":
    "Se o bot usa um segredo, envie também `x-zcode-bot-secret`; depois volte aqui após a vinculação ser concluída.",
