    "Roteie o tráfego de saída de modelo, MCP, ferramenta de comando, extensão e renderizador do app por este proxy; as variáveis de ambiente do sistema não são lidas. Deixe em branco e esse tráfego se conectará diretamente, enquanto o navegador integrado segue as configurações de proxy do sistema. Reinicie o app para aplicar; para extensões, você também pode executar \"Recarregar extensões\" na central de comandos.",
  "settings.httpProxyPlaceholder":
    "Em branco, o navegador integrado segue o proxy do sistema, ex.: http://127.0.0.1:7890",
  "settings.httpProxyNoProxy": "Sem proxy",
  "settings.httpProxyNoProxyDescription":
    "Requisições para esses hosts se conectam diretamente, sem usar o proxy HTTP. Separe as regras por vírgulas. Reinicie o app para aplicar.",
  "settings.httpProxyNoProxyPlaceholder": "ex.: localhost,127.0.0.1,::1,.example.com,*.corp.com",
  "settings.httpProxyCaCertPath": "Certificado personalizado",
  "settings.httpProxyCaCertPathDescription":
    "Opcional. Defina o caminho de um certificado raiz PEM para injetá-lo como NODE_EXTRA_CA_CERTS em modelos, MCP, ferramentas de comando e extensões, e para confiar nele na verificação de certificados do renderer. Reinicie o app para aplicar.",
  "settings.httpProxyCaCertPathPlaceholder": "ex.: /Users/name/certs/root-ca.pem",
  "settings.httpProxySavedHint": "Configurações de proxy de rede salvas. Reinicie o app para aplicar.",
  "settings.desktopChromiumHardwareAcceleration": "Aceleração de hardware do Chrome",
