  "settings.modelProvider.fieldHelp": "Sobre {field}",
  "settings.modelProvider.help.contextWindow":
    "A capacidade de contexto que o modelo consegue processar de uma vez, em tokens. O Biolecce Code usa isso para gerenciar o contexto.\nNão exceda o limite real do modelo.",
  "settings.modelProvider.help.maxOutputTokens":
    "O número máximo de tokens que uma única solicitação ao modelo pode gerar.\nNão exceda o limite real do modelo.",
  "settings.modelProvider.help.inputModalities":
    "Defina os tipos de conteúdo que o modelo pode receber:\n\n- **Texto**: Recebe conteúdo de texto. Obrigatório.\n- **Imagens**: Recebe conteúdo de imagem.\n- **Vídeo**: Recebe conteúdo de vídeo.\n- **PDF**: Recebe documentos PDF diretamente.",
  "settings.modelProvider.help.outputModalities":
    "O tipo de conteúdo das respostas do modelo. No momento, apenas texto é suportado.",
  "settings.modelProvider.help.capabilities":
    "- **Saída estruturada**: Suporta restrições de JSON Schema em campos, tipos e estrutura da saída.\n- **Pesquisa na web nativa**: Suporta o recurso de pesquisa na web integrado à API do modelo.\n- **Mensagens de sistema no meio da conversa**: Suporta a inserção de instruções de sistema durante uma conversa.\n\nNão ative recursos que o modelo não suporta.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Defina os níveis de raciocínio disponíveis na conversa. **Eles devem ser ordenados do menor para o maior esforço de raciocínio**.\nNão configure níveis de raciocínio que o modelo não suporta.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Use uma expressão CEL para mapear o nível de raciocínio atual, `reasoningLevel`, para campos da solicitação da API do modelo. O objeto JSON retornado pela expressão é mesclado ao corpo da solicitação enviada.",
  "settings.modelProvider.help.advanced":
    "**Esquema de ferramentas MFJS**: Ativa a compatibilidade com Moonshot Flavored JSON Schema, comumente usada pela API do modelo Kimi da Moonshot. Ative apenas quando a API do modelo exigir este formato.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Corresponde à configuração recomendada usando o ID do modelo, a URL base e o formato da API. O Biolecce Code atualiza continuamente as recomendações e as sincroniza automaticamente com você.\nQuando você altera manualmente uma configuração, ela passa a ser gerenciada manualmente e deixa de acompanhar as atualizações de recomendação; as demais configurações continuam gerenciadas pela configuração inteligente.",
